import re
from difflib import SequenceMatcher

from calhacks_contracts import GateInput

from features._text import normalize
from gatepy.registry import feature


def _norm_domain(d: str) -> str:
    d = normalize(d)
    d = re.sub(r"^(https?://)?(www\.)?", "", d).split("/")[0]
    return re.sub(r"[^0-9a-zÀ-￿]", "", d)


@feature("domain_known", monotone=-1)
def domain_known(x: GateInput) -> float:
    d = x.listing.seller.domain.lower()
    return 1.0 if any(k.domain.lower() == d for k in x.references.known_sellers) else 0.0


@feature("domain_similarity_to_known", monotone=1)
def domain_similarity_to_known(x: GateInput) -> float:
    """How close the domain is to a known store's domain when it is NOT that domain (0 for an exact match)."""
    d = x.listing.seller.domain.lower()
    nd = _norm_domain(d)
    return max((SequenceMatcher(None, nd, _norm_domain(k.domain)).ratio()
                for k in x.references.known_sellers if k.domain.lower() != d), default=0.0)

feature_sources.hidden.py:
import unicodedata

from calhacks_contracts import GateInput

from features._text import WORD, ZERO_WIDTH, all_text, scripts
from gatepy.registry import feature


@feature("hidden_chars", monotone=1)
def hidden_chars(x: GateInput) -> float:
    """Zero-width and other invisible format characters in the raw text (hidden text is evidence)."""
    return float(sum(ch in ZERO_WIDTH or unicodedata.category(ch) == "Cf" for ch in all_text(x)))


@feature("mixed_script_words", monotone=1)
def mixed_script_words(x: GateInput) -> float:
    """Words that mix alphabets, e.g. a Cyrillic 'а' inside a Latin word (homoglyph tricks)."""
    return float(sum(len(scripts(w)) > 1 for w in WORD.findall(all_text(x))))

feature_sources.injection.py:
import re

from calhacks_contracts import GateInput

from features._text import PATTERNS, item_text, normalize
from gatepy.registry import feature

AGENT_WORDS = re.compile(r"\b(ai|a\.i\.|llm|assistant|agent|bot|model|gpt|claude|shopping assistant)s?\b")
IMPERATIVE = re.compile(r"\b(must|should|do not|don't|never|always|immediately|ignore|override|proceed|skip|complete)\b")


def _hits(text: str) -> float:
    t = normalize(text)
    return float(sum(len(p.findall(t)) for p in PATTERNS))


@feature("injection_hits_text", monotone=1)
def injection_hits_text(x: GateInput) -> float:
    """Known injection patterns in the item text, after normalization (invisible characters removed)."""
    return _hits(item_text(x))


@feature("injection_hits_reviews", monotone=1)
def injection_hits_reviews(x: GateInput) -> float:
    return float(sum(_hits(r) for r in x.listing.reviews))


@feature("imperative_to_agent", monotone=1)
def imperative_to_agent(x: GateInput) -> float:
    """Sentences that both address an AI/agent and give an order."""
    n = 0
    for chunk in [item_text(x), *x.listing.reviews]:
        for s in re.split(r"(?<=[.!?])\s+|\n", normalize(chunk)):
            n += bool(AGENT_WORDS.search(s) and IMPERATIVE.search(s))
    return float(n)

